mapper.select:
SELECT d.*, o.org_name AS orgName
FROM agri_iot_device d
LEFT JOIN agri_md_organization o ON d.org_id = o.id
WHERE d.del_flag = 0

    AND d.device_code LIKE CONCAT('%', #{dto.deviceCode}, '%')


    AND d.device_name LIKE CONCAT('%', #{dto.deviceName}, '%')


    AND d.device_type = #{dto.deviceType}


    AND d.org_id = #{dto.orgId}


    AND d.status = #{dto.status}

ORDER BY d.create_time DESC
LIMIT #{dto.pageNum}, #{dto.pageSize}

SELECT COUNT(*)
FROM agri_iot_device d
WHERE d.del_flag = 0

    AND d.device_code LIKE CONCAT('%', #{dto.deviceCode}, '%')


    AND d.device_name LIKE CONCAT('%', #{dto.deviceName}, '%')


    AND d.device_type = #{dto.deviceType}


    AND d.org_id = #{dto.orgId}


    AND d.status = #{dto.status}
